def paragraph_text(paragraph: ET.Element) -> str:
    texts = []
    for text_node in paragraph.findall(".//w:t", NS):
        if text_node.text:
            texts.append(text_node.text)
    return "".join(texts).strip()


def replace_paragraph_text(paragraph: ET.Element, new_text: str) -> None:
    ppr = paragraph.find(f"{{{W_NS}}}pPr")
    first_run = paragraph.find(f".//{{{W_NS}}}r")
    run_properties = None
    if first_run is not None:
        rpr = first_run.find(f"{{{W_NS}}}rPr")
        if rpr is not None:
            run_properties = copy.deepcopy(rpr)

    for child in list(paragraph):
        if child is ppr:
            continue
        paragraph.remove(child)

    new_run = ET.Element(f"{{{W_NS}}}r")
    if run_properties is not None:
        new_run.append(run_properties)

    text_element = ET.Element(f"{{{W_NS}}}t")
    text_element.set(f"{{{XML_NS}}}space", "preserve")
    text_element.text = new_text
    new_run.append(text_element)
    paragraph.append(new_run)


def update_docx(source: Path, destination: Path) -> tuple[int, list[str]]:
    with zipfile.ZipFile(source, "r") as source_zip:
        source_entries = [(info, source_zip.read(info.filename)) for info in source_zip.infolist()]
        document_xml = source_zip.read("word/document.xml")

    root = ET.fromstring(document_xml)
    paragraphs = root.findall(".//w:p", NS)
    replaced_texts: list[str] = []

    for paragraph in paragraphs:
        current_text = paragraph_text(paragraph)
        replacement = REPLACEMENTS.get(current_text)
        if replacement:
            replace_paragraph_text(paragraph, replacement)
            replaced_texts.append(current_text)

    missing = [original for original in REPLACEMENTS if original not in replaced_texts]

    if missing:
        raise RuntimeError(
            f"Could not find {len(missing)} target paragraph(s) in the document. First missing entry: {missing[0][:120]}"
        )

    updated_xml = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    with zipfile.ZipFile(destination, "w") as output_zip:
        for info, content in source_entries:
            if info.filename == "word/document.xml":
                output_zip.writestr(info, updated_xml)
            else:
                output_zip.writestr(info, content)

    return len(replaced_texts), missing


